contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param: an address proposed as the new owner
    function testFuzz_property(address proposedOwner) public {
        // keep domain wide but avoid zero address to be more realistic
        vm.assume(proposedOwner != address(0));

        // admin is the deployer (this contract created c in setUp), so we must call as that admin
        // setOwner is restricted to onlyAdmin (the deployer of C), which is address(this) from setUp
        // call setOwner with the fuzzed proposedOwner
        bool ok;
        try c.setOwner(proposedOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: when the admin calls setOwner(x) it sets owner() == x
        // We assert that the call succeeded and that owner equals the provided address.
        // (This single assertion will hold for the reference; the mutant will set owner==admin
        // so for any proposedOwner != admin this assertion will fail.)
        assertTrue(ok && c.owner() == proposedOwner);
    }
}

