    C c;
    function setUp() public { c = new C(); }

    // fuzz the candidate owner address; the property: after admin calls setOwner(_owner), c.owner() == _owner
    // the mutant sets owner = msg.sender, so when _owner != admin the mutant will fail.
    function testFuzz_property(address candidateOwner) public {
        // keep the domain wide but avoid zero address to be explicit (still admissible broadly)
        vm.assume(candidateOwner != address(0));

        // admin is the deployer (address(this) in setUp). We must call setOwner as admin.
        // use vm.prank to make the call from the deploying address (address(this)) which is admin.
        vm.prank(address(this));
        bool ok;
        try c.setOwner(candidateOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // single assertion: reference contract guarantees that owner equals the provided candidateOwner
        // (and returns true). The mutant will set owner to msg.sender (admin) instead when candidateOwner != admin,
        // causing this assertion to fail for those inputs.
        assertTrue(ok && c.owner() == candidateOwner);
    }
}

