pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: an address that attempts to call setOwner to change owner to some target
    // General rule: only the original deployer (admin) can successfully call setOwner on the reference
    // but the mutant allows the current owner to call setOwner; thus there exists an address (=current owner)
    // for which mutant accepts while reference rejects.
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses from being zero to be in wide admissible domain but avoid trivial zero-address scenarios
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Ensure caller is not the deployer (admin). The admin is address(this) in setUp deployment context? No: admin was set to msg.sender at C construction time; since we called new C() from this test contract, admin == address(this).
        // We want to test the distinguishing case: when caller == current owner (which initially is also address(this)), but fuzz supplies caller; we will set owner to caller only if the admin calls setOwner.

        // First, as admin (this contract) set owner to caller so that caller becomes owner in both reference and mutant.
        bool ok;
        // call setOwner as admin (test contract) — should succeed on reference and mutant because at deployment admin was test contract
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // If this setup failed for some reason, we cannot proceed meaningfully; require it succeeded.
        // This call should always succeed on the reference contract for any caller address, so keep only those traces.
        if (!ok) return;

        // Now caller is the owner according to c.owner()
        address currentOwner = c.owner();
        // sanity: should equal caller
        vm.assume(currentOwner == caller);

        // Now attempt to have caller call setOwner to change owner to newOwner.
        // In the reference, only admin (this test contract) can call setOwner, so this should fail when caller != admin (address(this)).
        // In the mutant, only owner can call setOwner, so this will succeed when caller == owner.

        // ensure caller is not admin so that reference will reject the call and mutant (when caller==owner) will accept — fuzz will search such inputs
        vm.assume(caller != address(this));

        // Make the call as the fuzzed caller and capture whether it succeeded
        bool successCall;
        vm.prank(caller);
        try c.setOwner(newOwner) {
            successCall = true;
        } catch {
            successCall = false;
        }

        // Single assertion: on the reference contract, the call must NOT succeed when msg.sender != admin.
        // Because this test runs against the reference C, for ALL admissible inputs where caller != admin, the call should fail.
        // The mutant (where onlyAdmin compares to owner) would allow the call to succeed when caller == owner and caller != admin — the fuzzer can find such inputs and make the mutant pass where reference rejects.
        assertTrue(!successCall);
    }
}

