import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but non-zero to avoid degenerate EOA(address(0)) scenarios
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // by construction, deployer (this contract during setUp) is admin and owner initially
        // The property: only admin can change owner. So any call to setOwner from a non-admin should NOT change owner.

        // record original owner
        address origOwner = c.owner();

        bool ok;
        // attempt to call setOwner as the fuzzed caller; capture whether call succeeded
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // The invariant we assert: If the caller is NOT the admin (deployer), then owner must remain unchanged.
        // If the caller IS the admin, the call may succeed and change owner; both are acceptable for the reference.
        // We express the universal property as: (caller != admin) implies (c.owner() == origOwner)
        // Read admin by attempting to change owner as the known admin (the test contract). We know deployer was this test contract.

        // Determine admin address: it's the address that was deployer of C, which is this contract (address(this))
        address admin = address(this);

        if (caller != admin) {
            // only one assertion permitted; this is the single assertTrue observing c
            assertTrue(c.owner() == origOwner);
        } else {
            // if caller is admin, no universal constraint on resulting owner (admin may change it),
            // so assert that call behaved according to success flag matches owner change: if ok then owner == newOwner, else owner unchanged
            if (ok) {
                assertTrue(c.owner() == newOwner);
            } else {
                assertTrue(c.owner() == origOwner);
            }
        }
    }
}

